// WORKER_BASE precisa bater com WORKER_BASE_URL do .env da esteira.
// Ver n8n/COMO-IMPORTAR.md.
const WORKER_BASE = 'http://localhost:5000';
const msg = $('Buscar cabeçalhos completos no Graph').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.reply_to);
const norm = (v) => String(v ?? '').trim().toLowerCase();
const headers = Object.fromEntries((msg.internetMessageHeaders ?? []).map(h => [norm(h.name), String(h.value ?? '')]));
const idsCabecalho = `${headers['in-reply-to'] ?? ''} ${headers.references ?? ''}`.match(/<[^>]+>|[^\s]+/g) ?? [];
let registro = null;
let criterio = '';
for (const id of idsCabecalho) {
  registro = rows.find(r => norm(r.internet_message_id) === norm(id));
  if (registro) { criterio = 'In-Reply-To/References'; break; }
}
if (!registro && msg.conversationId) {
  registro = rows.find(r => norm(r.conversation_id) === norm(msg.conversationId));
  if (registro) criterio = 'conversationId';
}
// Caminho 3 — o assunto. É o último recurso, e por isso NÃO pode depender
// da Data Table: se o banco do n8n for perdido ou reiniciado, toda pergunta
// pendente ficaria órfã, que é exatamente o que o n8n/README.md promete que
// não acontece. O assunto carrega tudo que é preciso.
//
// [esteira #1001-2] → demanda 1001, pergunta 2 → reply_to reconstruído.
// O segundo número é o número da PERGUNTA (esteira-ask usa
// proxima_pergunta_id), não a rodada. Confira em bin/esteira-ask e no
// comm.envelope antes de mexer nisto.
if (!registro) {
  const m = String(msg.subject ?? '').match(/\[esteira #(\d+)-(\d+)\]/i);
  if (m) {
    const logico = `${m[1]}-${m[2]}`;
    registro = rows.find(r => norm(r.logical_message_id) === norm(logico));
    if (registro) {
      criterio = 'assunto';
    } else {
      // Sem linha na tabela: reconstrói. Mesmo formato do comm.envelope,
      // reply_to = {WORKER_BASE}/answer/{demanda}/{demanda}-{n}
      registro = { reply_to: `${WORKER_BASE}/answer/${m[1]}/${logico}` };
      criterio = 'assunto (reconstruído, sem Data Table)';
    }
  }
}
const remetente = msg.from?.emailAddress?.address || msg.from?.emailAddress?.name || msg.sender?.emailAddress?.address || 'equipe';
if (!registro) return [{ json: { casou: false, mensagem_id: msg.id, autor: remetente, assunto: msg.subject ?? '', motivo: 'Nenhum identificador conhecido casou.' } }];
let corpo = msg.body?.content ?? msg.bodyPreview ?? '';
if (String(msg.body?.contentType ?? '').toLowerCase() === 'html') {
  corpo = String(corpo).replace(/<br\s*\/?\s*>/gi, '\n').replace(/<\/(p|div|li|h[1-6])>/gi, '\n').replace(/<[^>]*>/g, ' ');
  corpo = corpo.replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'");
}
corpo = String(corpo).split(/--- responda acima desta linha ---/i)[0];
corpo = corpo.split(/\r?\n/).filter(l => !/^\s*>/.test(l)).join('\n').trim();
return [{ json: { casou: true, resposta: corpo, autor: remetente, reply_to: registro.reply_to, criterio, mensagem_id: msg.id, assunto: msg.subject ?? '' } }];
